class InterruptablePool<T> extends Pool<T> {

  // Holds the thread currently blocked in pollEntry(), or null when no thread is blocking. It is
  // written by the fetcher thread and read by the thread calling wakeup(), so it must be safely
  // published across threads - an AtomicReference (like a volatile) guarantees that visibility.
  private final AtomicReference<Thread> blockedThread = new AtomicReference<>();

  InterruptablePool(int poolCapacity) {
    super(poolCapacity);
  }

  @Override
  public T pollEntry() throws InterruptedException {
    blockedThread.set(Thread.currentThread());
    try {
      return super.pollEntry();
    } finally {
      blockedThread.set(null);
    }
  }

  /**
   * Interrupts the thread (if any) currently blocked in {@link #pollEntry()}. This is safe to call
   * from a thread other than the one blocked in {@code pollEntry()}.
   */
  void wakeup() {
    Thread thread = blockedThread.get();
    if (thread != null) {
      thread.interrupt();
    }
  }
}
```

